// Walk and wing-beat cycles (4 frames) for the enemy families. Each body comes unchanged from the approved
// refined-v3 sprite (tools/art/png2pxl.py --part, regenerated by tools/art/build_anims.py);
// only the legs move. The game already adds hop/squash in code (GemArt.enemy_motion), so no
// body bob here. Frames 0 and 2 are the contacts that land with the hop.
//
// A leg: rects [x0, x1, y0, y1] (inclusive) that hold it, the pivot row where it meets the body,
// the length over which the shear grows, and per frame [hoof offset px (+ = forward), lift px].
// Legs are listed far -> near; nearer legs are drawn last.

// Near front leg swings the most; the diagonal partner moves with it, the other pair opposite.
const NEAR_FRONT = [[4, 0], [0, 0], [-3, 0], [0, 2]]
const FAR_FRONT = [[-2, 0], [0, 1], [2, 0], [0, 0]]
// A hind leg drawn at its rear extreme (boar, hound) can only swing forward.
const HIND_FROM_REAR = [[0, 0], [2, 1], [4, 0], [2, 0]]
const HIND = [[-2, 0], [0, 1], [3, 0], [0, 0]]
// A far front leg already touching the right edge (frog, robot, boss) can only swing back.
const FAR_FRONT_FROM_FORWARD = [[-3, 0], [-1, 1], [0, 0], [-1, 0]]
// Spiders: two alternating leg groups that tiptoe (lift high, short steps, never past the edge).
const SPIDER_A = [[0, 0], [1, 1], [2, 0], [1, 0]]
const SPIDER_B = [[2, 0], [1, 0], [0, 0], [1, 1]]

// Flyers (frames follow time; GemArt.enemy_motion lifts the body most at frame 1, mid
// down-stroke). Wings are drawn raised, so frame 0 is the top of the beat.
// A sideways wing: { rects, pivotX: shoulder column, reach: px to the tip, flap: tip drop per frame }.
const WING_DOWN = [0, 3, 5, 3]
// An upright wing reuses the leg shear with a negative length (pivot row below the tip):
// it tips forward and down on the down-stroke.
const UPRIGHT_WING = [[0, 0], [2, -1], [4, -3], [2, -1]]

function hex(color) {
  return "#" + color.toString(16).padStart(8, "0")
}

// All legs are lifted off first, then redrawn sheared, so a leg swinging into another leg's
// rects is never erased by it. Colours are copied raw, so every part keeps its own palette.
function moveLegs(c, legs) {
  const lifted = legs.map((leg) => {
    const pixels = []
    for (const [x0, x1, y0, y1] of leg.rects)
      for (let y = y0; y <= y1; y++)
        for (let x = x0; x <= x1; x++) {
          if (!c.is(x, y, ".")) pixels.push([x, y, hex(c.get(x, y))])
          c.px(x, y, "_")
        }
    return pixels
  })
  legs.forEach((leg, i) => {
    if (leg.shift) {
      // Whole part moves (balloons bob, claws reach).
      const [dx, dy] = leg.shift[c.frame]
      for (const [x, y, color] of lifted[i]) c.px(x + dx, y + dy, color)
      return
    }
    if (leg.spin) {
      // Rotor seen edge-on: squeeze the blades towards the hub column.
      for (const [x, y, color] of lifted[i]) c.px(Math.round(leg.spinX + (x - leg.spinX) * leg.spin[c.frame]), y, color)
      return
    }
    if (leg.wave) {
      // Cloth or robe: columns ripple on a travelling sine wave.
      const { amp, period } = leg.wave
      for (const [x, y, color] of lifted[i]) c.px(x, y + Math.round(amp * Math.sin(x / period + c.frame * Math.PI / 2)), color)
      return
    }
    if (leg.pivotX !== undefined) {
      // Wing spread sideways: columns drop by their distance from the shoulder column.
      for (const [x, y, color] of lifted[i]) {
        const t = Math.min(1, Math.abs(x - leg.pivotX) / leg.reach)
        c.px(x, y + Math.round(leg.flap[c.frame] * t), color)
      }
      return
    }
    const [dx, lift] = leg.swing[c.frame]
    for (const [x, y, color] of lifted[i]) {
      // Shear around the pivot: the hoof moves the full offset, the hip/shoulder stays put.
      const t = (y - leg.top) / leg.len
      c.px(x + Math.round(dx * t), y - Math.round(lift * t), color)
    }
  })
}

function walk(name, part, w, h, legs) {
  anim(name, { w, h, frames: 4, fps: 8 }, stamp(part, 0, 0), (c) => moveLegs(c, legs))
}

// refined-v4 bodies: the canvas gets a margin so swinging feet and beating wings are not cut off;
// legs are given in the sprite's own coordinates and offset here.
const PAD = 4
function walk4(name, part, w, h, legs) {
  // Legs: one extra column each side and down to the last row, so no hoof edge is left behind.
  const grow = (leg) => leg.swing && leg.len > 0 && leg.grow !== false
  const moved = legs.map((leg) => ({
    ...leg,
    rects: leg.rects.map(([x0, x1, y0, y1]) => grow(leg) ? [x0 - 1 + PAD, x1 + 1 + PAD, y0 + PAD, h - 1 + PAD] : [x0 + PAD, x1 + PAD, y0 + PAD, y1 + PAD]),
    top: leg.top === undefined ? undefined : leg.top + PAD,
    pivotX: leg.pivotX === undefined ? undefined : leg.pivotX + PAD,
    spinX: leg.spinX === undefined ? undefined : leg.spinX + PAD,
  }))
  anim(name, { w: w + 2 * PAD, h: h + 2 * PAD, frames: 4, fps: 8 }, stamp(part, PAD, PAD), (c) => { moveLegs(c, moved); despeckle(c) })
}

// A refined-v4 body is one connected shape; specks a moved leg leaves behind are removed.
function despeckle(c, min = 16) {
  const seen = new Set()
  for (let y = 0; y < c.h; y++)
    for (let x = 0; x < c.w; x++) {
      if (c.is(x, y, ".") || seen.has(x + "," + y)) continue
      const part = [[x, y]], stack = [[x, y]]
      seen.add(x + "," + y)
      while (stack.length) {
        const [px, py] = stack.pop()
        for (const [nx, ny] of [[px + 1, py], [px - 1, py], [px, py + 1], [px, py - 1]]) {
          const key = nx + "," + ny
          if (nx < 0 || ny < 0 || nx >= c.w || ny >= c.h || seen.has(key) || c.is(nx, ny, ".")) continue
          seen.add(key); part.push([nx, ny]); stack.push([nx, ny])
        }
      }
      if (part.length < min) for (const [px, py] of part) c.px(px, py, "_")
    }
}
// Steps for the larger refined-v4 legs: pair A reaches forward on frame 0, pair B on frame 2,
// each lifting while it swings forward (as NEAR_FRONT / HIND above).
const STEP_A = [[3, 0], [0, 0], [-3, 0], [0, 2]]
const STEP_B = [[-3, 0], [0, 2], [3, 0], [0, 0]]
const SMALL_A = [[2, 0], [0, 0], [-2, 0], [0, 1]]
const SMALL_B = [[-2, 0], [0, 1], [2, 0], [0, 0]]
const HOP = [[0, 0], [0, 2], [0, 0], [0, 2]]
const SWAY = [-2, 0, 2, 0]
const BEAT = [0, 3, 5, 3]
const BEAT_SMALL = [0, 2, 3, 2]
const BOB = [[0, 0], [0, 1], [0, 1], [0, 0]]


